  const hTwips = Math.round(heightMm / 25.4 * 1440);
  const marginTwips = Math.max(120, Math.round((Number(layout?.page?.marginMm) || 18) / 25.4 * 1440));
  const sectPr = `<w:sectPr><w:pgSz w:w="${wTwips}" w:h="${hTwips}"/><w:pgMar w:top="${marginTwips}" w:right="${marginTwips}" w:bottom="${marginTwips}" w:left="${marginTwips}" w:header="720" w:footer="720" w:gutter="0"/></w:sectPr>`;
