      item.addEventListener('dragstart', e => { draggedPage = p.index; item.classList.add('is-dragging'); if (e.dataTransfer) { e.dataTransfer.effectAllowed = 'move'; e.dataTransfer.setData('text/plain', String(p.index)); } });
      item.addEventListener('dragend', () => { draggedPage = null; item.classList.remove('is-dragging'); for (const x of this.pageNavEl.querySelectorAll('.is-drop-target')) x.classList.remove('is-drop-target'); });
      item.addEventListener('dragover', e => { if (draggedPage == null || draggedPage === p.index) return; e.preventDefault(); item.classList.add('is-drop-target'); });
