    const fr = flow.getBoundingClientRect();
    if (evt.clientX < fr.left - 38 || evt.clientX > fr.left + 14 || evt.clientY < fr.top || evt.clientY > fr.bottom) { gutter.classList.remove('is-visible'); return; }
    const blocks = [...flow.querySelectorAll('.mw-block')];
    const pr = page.getBoundingClientRect();
    let before = '', after = '', y = fr.top + 5;
    if (!blocks.length) { y = fr.top + 8; }
    else {
      const cy = evt.clientY;
      let placed = false;
      for (let i = 0; i < blocks.length; i++) {
        const r = blocks[i].getBoundingClientRect();
        if (cy <= r.top + r.height / 2) { before = blocks[i].dataset.nodeId || ''; after = i ? blocks[i-1].dataset.nodeId || '' : ''; y = r.top; placed = true; break; }
      }
      if (!placed) { const r = blocks[blocks.length - 1].getBoundingClientRect(); after = blocks[blocks.length-1].dataset.nodeId || ''; y = r.bottom + 2; }
    }
    gutter.dataset.beforeNodeId = before; gutter.dataset.afterNodeId = after;
    gutter.style.left = `${Math.max(4, this.pagePaddingPx - 28)}px`; gutter.style.top = `${Math.max(3, (y - pr.top) / Math.max(.01, this.viewZoom) - 9)}px`; gutter.classList.add('is-visible');
