    const blocks = p ? [...p.flow.querySelectorAll('.mw-block')] : [];
    if (blocks.length) {
      const id = blocks[blocks.length - 1].dataset.nodeId;
      const idx = this.doc.nodes.findIndex(n => n.id === id);
      if (idx >= 0) return idx;
    }
