'use strict';

const { Plugin, MarkdownView, Notice, TFile } = require('obsidian');
const { MarkdownWordPageView, VIEW_TYPE } = require('./lib/page-view');

module.exports = class MarkdownWordPlugin extends Plugin {
  async onload() {
    this.registerView(VIEW_TYPE, leaf => new MarkdownWordPageView(leaf, this));

    this.addCommand({
      id: 'open-page-mode',
      name: 'Open current note in page mode',
      checkCallback: (checking) => {
        const view = this.app.workspace.getActiveViewOfType(MarkdownView);
        if (!view?.file) return false;
        if (!checking) this.openPageView(view.file);
        return true;
      },
    });

    const activePage = () => {
      const leaf = this.app.workspace.getMostRecentLeaf?.();
      const view = leaf?.view;
      return view?.getViewType?.() === VIEW_TYPE ? view : null;
    };
    const pageCommand = (id, name, fn) => this.addCommand({
      id, name,
      checkCallback: checking => {
        const view = activePage(); if (!view) return false;
        if (!checking) fn(view); return true;
      },
    });

    // These commands deliberately have no forced global hotkeys. The page editor
    // already supports Word-like Ctrl/Cmd+B, Ctrl/Cmd+I, Ctrl/Cmd+Shift+X and
    // Ctrl/Cmd+Alt+1/2/3 locally; users can additionally bind these commands in
    // Settings → Hotkeys without colliding with normal Obsidian editing.
    pageCommand('format-bold', 'Format: Bold in Markdown Word', v => v.applyRichCommand('bold'));
    pageCommand('format-italic', 'Format: Italic in Markdown Word', v => v.applyRichCommand('italic'));
    pageCommand('format-strike', 'Format: Strikethrough in Markdown Word', v => v.applyRichCommand('strikeThrough'));
    pageCommand('heading-1', 'Format: Heading 1 in Markdown Word', v => v.setActiveBlockType('heading', 1));
    pageCommand('heading-2', 'Format: Heading 2 in Markdown Word', v => v.setActiveBlockType('heading', 2));
    pageCommand('heading-3', 'Format: Heading 3 in Markdown Word', v => v.setActiveBlockType('heading', 3));
    pageCommand('insert-table', 'Insert table in Markdown Word', v => v.insertTable(3, 3));
    pageCommand('draw-arrow', 'Draw arrow in Markdown Word', v => v.toggleDrawMode('arrow'));
    pageCommand('draw-line', 'Draw line in Markdown Word', v => v.toggleDrawMode('line'));
    pageCommand('draw-dashed-line', 'Draw dashed line in Markdown Word', v => v.toggleDrawMode('dashline'));
    pageCommand('draw-rectangle', 'Draw rectangle in Markdown Word', v => v.toggleDrawMode('rect'));
    pageCommand('draw-ellipse', 'Draw ellipse in Markdown Word', v => v.toggleDrawMode('ellipse'));
    pageCommand('delete-selected-pages', 'Delete selected pages in Markdown Word', v => v.deletePages([...v.selectedPages]));
    pageCommand('undo', 'Undo in Markdown Word', v => v.undo());
    pageCommand('redo', 'Redo in Markdown Word', v => v.redo());

    this.addRibbonIcon('file-text', 'Open current note in Markdown Word page mode', () => {
      const file = this.app.workspace.getActiveFile();
      if (file?.extension === 'md') this.openPageView(file);
      else new Notice('请先打开一个 Markdown 文件。');
    });

    this.registerEvent(this.app.workspace.on('file-menu', (menu, file) => {
      if (!(file instanceof TFile) || file.extension !== 'md') return;
      menu.addItem(item => item.setTitle('Open in Markdown Word page mode').setIcon('file-text').onClick(() => this.openPageView(file)));
    }));
  }

  async openPageView(file) {
    if (!file) return;
    for (const leaf of this.app.workspace.getLeavesOfType(VIEW_TYPE)) {
      const view = leaf.view;
      if (view?.file?.path === file.path || view?.getState?.()?.file === file.path) {
        this.app.workspace.revealLeaf(leaf); return;
      }
    }
    const leaf = this.app.workspace.getLeaf(false);
    await leaf.setViewState({ type: VIEW_TYPE, active: true, state: { file: file.path } });
    this.app.workspace.revealLeaf(leaf);
  }

  onunload() { this.app.workspace.detachLeavesOfType(VIEW_TYPE); }
};

